/// <reference lib="webworker" />
import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching';
import { registerRoute, NavigationRoute } from 'workbox-routing';
import { StaleWhileRevalidate, CacheFirst, NetworkOnly } from 'workbox-strategies';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';
import { ExpirationPlugin } from 'workbox-expiration';

declare const self: ServiceWorkerGlobalScope;

cleanupOutdatedCaches();

// Precache all assets generated by Vite build
precacheAndRoute(self.__WB_MANIFEST);

// SPA Navigation fallback
const navigationRoute = new NavigationRoute(
  async ({ event }) => {
    try {
      const preloadResponse = await (event as FetchEvent).preloadResponse;
      if (preloadResponse) return preloadResponse;
      return (await caches.match('/index.html')) || (await fetch('/index.html'));
    } catch {
      return (await caches.match('/offline')) || (await caches.match('/index.html')) || new Response('Offline', { status: 200 });
    }
  },
  {
    denylist: [/^\/api\//, /^\/socket\.io\//],
  },
);
registerRoute(navigationRoute);

// Section 9.4: Strictly NetworkOnly (never cache) for authenticated API routes
registerRoute(
  ({ url }) =>
    url.pathname.startsWith('/api/v1/auth') ||
    url.pathname.startsWith('/api/v1/consultations') ||
    url.pathname.startsWith('/api/v1/reports') ||
    url.pathname.startsWith('/api/v1/screenings') ||
    url.pathname.startsWith('/api/v1/sync') ||
    url.pathname.startsWith('/api/v1/phc') ||
    url.pathname.startsWith('/api/v1/district') ||
    url.pathname.startsWith('/api/v1/profile'),
  new NetworkOnly(),
);

// Cache configurations and static guidance assets with StaleWhileRevalidate
registerRoute(
  ({ url }) => url.pathname.startsWith('/api/v1/config/'),
  new StaleWhileRevalidate({
    cacheName: 'healthsetu-config-cache',
    plugins: [
      new CacheableResponsePlugin({ statuses: [200] }),
      new ExpirationPlugin({ maxAgeSeconds: 7 * 24 * 3600 }),
    ],
  }),
);

// Cache facility exports with StaleWhileRevalidate
registerRoute(
  ({ url }) => url.pathname.startsWith('/api/v1/facilities/export'),
  new StaleWhileRevalidate({
    cacheName: 'healthsetu-facilities-cache',
    plugins: [
      new CacheableResponsePlugin({ statuses: [200] }),
      new ExpirationPlugin({ maxAgeSeconds: 7 * 24 * 3600 }),
    ],
  }),
);

// Cache audio assets with CacheFirst (Opus/MP3 pre-generated voice)
registerRoute(
  ({ request, url }) => request.destination === 'audio' || url.pathname.startsWith('/audio/'),
  new CacheFirst({
    cacheName: 'healthsetu-audio-cache',
    plugins: [
      new CacheableResponsePlugin({ statuses: [200] }),
      new ExpirationPlugin({ maxEntries: 200, maxAgeSeconds: 30 * 24 * 3600 }),
    ],
  }),
);

// Listen for skip waiting message
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});
